using Microsoft.AspNetCore.Mvc; using NexusTelecommunicationManagementSystem.Models; using NexusTelecommunicationManagementSystem.Services;
namespace NexusTelecommunicationManagementSystem.Controllers;
public class AdminController:Controller{private readonly NexusService _s;public AdminController(NexusService s)=>_s=s;
 private bool Guard(){if(HttpContext.Session.GetString("Role")!="Admin"){Response.Redirect(Url.Action("AdminLogin","Account")!);return false;}return true;}
 public IActionResult Index()=>Guard()?View(_s.Dashboard()):new EmptyResult(); public IActionResult Orders()=>Guard()?View(_s.GetOrders()):new EmptyResult(); public IActionResult Connections()=>Guard()?View(_s.GetConnections()):new EmptyResult(); public IActionResult Customers()=>Guard()?View(_s.Customers()):new EmptyResult(); public IActionResult Employees()=>Guard()?View(_s.Employees()):new EmptyResult(); public IActionResult Vendors()=>Guard()?View(_s.Vendors()):new EmptyResult(); public IActionResult Shops()=>Guard()?View(_s.Shops()):new EmptyResult(); public IActionResult Equipment()=>Guard()?View(_s.Equipment()):new EmptyResult(); public IActionResult Billing()=>Guard()?View(_s.GetBills()):new EmptyResult(); public IActionResult Plans()=>Guard()?View(_s.Plans):new EmptyResult();
 [HttpPost][ValidateAntiForgeryToken]public IActionResult AddEmployee(string name,string role,string email,string username,string password){if(!Guard())return new EmptyResult();if(string.IsNullOrWhiteSpace(name)||string.IsNullOrWhiteSpace(role)||string.IsNullOrWhiteSpace(email)||string.IsNullOrWhiteSpace(username)||password.Length<8){TempData["Error"]="Complete employee fields and use a password of at least 8 characters.";return RedirectToAction(nameof(Employees));}try{_s.AddEmployee(name.Trim(),role.Trim(),email.Trim(),username.Trim(),password);}catch{TempData["Error"]="Could not create employee. Username/email may already exist.";}return RedirectToAction(nameof(Employees));}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult UpdateEmployee(int id,string name,string role,string email,string status,string username){if(!Guard())return new EmptyResult();_s.UpdateEmployee(id,name.Trim(),role.Trim(),email.Trim(),status,username.Trim());return RedirectToAction(nameof(Employees));}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult ResetEmployeePassword(int id,string password){if(!Guard())return new EmptyResult();if(password.Length<8){TempData["Error"]="Password must be at least 8 characters.";return RedirectToAction(nameof(Employees));}_s.ResetEmployeePassword(id,password);TempData["Message"]="Employee password reset.";return RedirectToAction(nameof(Employees));}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult UpdateOrder(string code,OrderStatus status){if(!Guard())return new EmptyResult();_s.SetOrderStatus(code,status);TempData["Message"]=$"Order {code} updated to {status}.";return RedirectToAction(nameof(Orders));}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult UpdateConnection(string accountId,ConnectionStatus status){if(!Guard())return new EmptyResult();_s.SetConnectionStatus(accountId,status);TempData["Message"]=$"Connection {accountId} updated to {status}.";return RedirectToAction(nameof(Connections));}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult AddCustomer(string name,string contact,string email,string city){if(!Guard())return new EmptyResult();if(!string.IsNullOrWhiteSpace(name))_s.AddCustomer(name.Trim(),contact.Trim(),email.Trim(),city.Trim());return RedirectToAction(nameof(Customers));}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult UpdateCustomer(int id,string name,string contact,string email,string address,string city){if(!Guard())return new EmptyResult();_s.UpdateCustomer(id,name.Trim(),email.Trim(),contact.Trim(),address.Trim(),city.Trim());TempData["Message"]="Customer record updated.";return RedirectToAction(nameof(Customers));}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult UpdateEquipment(int id,string name,string category,int quantity,int reorderLevel,string vendor){if(!Guard())return new EmptyResult();_s.UpdateEquipment(id,name.Trim(),category.Trim(),quantity,reorderLevel,vendor.Trim());TempData["Message"]="Equipment record updated.";return RedirectToAction(nameof(Equipment));}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult UpdateVendor(int id,string name,string contact,string category,string status){if(!Guard())return new EmptyResult();_s.UpdateVendor(id,name.Trim(),contact.Trim(),category.Trim(),status);TempData["Message"]="Vendor updated.";return RedirectToAction(nameof(Vendors));}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult UpdateShop(int id,string name,string city,string contact,string status){if(!Guard())return new EmptyResult();_s.UpdateShop(id,name.Trim(),city.Trim(),contact.Trim(),status);TempData["Message"]="Retail shop updated.";return RedirectToAction(nameof(Shops));}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult AddPlan(string name,ConnectionType type,decimal price,string cycle,string speed){if(!Guard())return new EmptyResult();if(!string.IsNullOrWhiteSpace(name))_s.AddPlan(name.Trim(),type,price,cycle.Trim(),speed.Trim());return RedirectToAction(nameof(Plans));}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult UpdatePlan(int id,string name,ConnectionType type,decimal price,string cycle,string speed,string description,bool active){if(!Guard())return new EmptyResult();_s.UpdatePlan(id,name.Trim(),type,price,cycle.Trim(),speed.Trim(),description.Trim(),active);TempData["Message"]="Plan updated.";return RedirectToAction(nameof(Plans));}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult MarkBillPaid(int id,decimal amount){if(!Guard())return new EmptyResult();_s.MarkBillPaid(id,amount);TempData["Message"]="Bill payment updated.";return RedirectToAction(nameof(Billing));}
 [HttpPost][ValidateAntiForgeryToken]public IActionResult ToggleCustomer(int id,bool active){if(!Guard())return new EmptyResult();_s.SetCustomerActive(id,active);return RedirectToAction(nameof(Customers));}
 public IActionResult Error()=>View(); }
